require_once __DIR__ . '/includes/visitor_portal.php';$pdo=db();$visitor=current_visitor($pdo);$token=$_SESSION['guest_profile_otp_token']??'';if(!$token)redirect('guest_profile.php');$error='';$success='';
if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();if(isset($_POST['resend_otp'])){$success=resend_otp($pdo,$token)?'A new OTP was sent.':'Please wait before requesting another code.';}else{$otp=trim($_POST['otp']??'');if(!preg_match('/^\d{6}$/',$otp))$error='OTP must be a 6-digit number.';else{$data=verify_otp($pdo,$token,$otp);if(!$data||($data['flow']??'')!=='guest_profile_update'||(int)$data['visitor_id']!==(int)$visitor['id'])$error='Invalid or expired OTP code.';else{$s=$pdo->prepare('UPDATE visitors SET contact_no=?,email=?,house_no=?,street=?,barangay=?,municipality=?,province=?,purpose=?,purpose_other=? WHERE id=?');$s->execute([$data['contact_no'],$data['email']?:null,$data['house_no'],$data['street'],$data['barangay'],$data['municipality'],$data['province'],$data['purpose'],$data['purpose']==='Others'?$data['purpose_other']:null,$visitor['id']]);$pdo->prepare('DELETE FROM otp_codes WHERE barcode=?')->execute([$token]);unset($_SESSION['guest_profile_otp_token']);visitor_log($pdo,$visitor['id'],'contact_number_change','Mobile number reverified through SMS OTP.');redirect('guest_profile.php');}}}}
visitor_portal_header('Verify Contact Number',$visitor);
?><h2>Verify New Mobile Number</h2><p class="text-muted">Enter the OTP sent to your new number before saving this change.</p><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><?php if($success):?><div class="alert alert-success"><?=e($success)?></div><?php endif;?><div class="card"><div class="card-body"><form method="post"><?=csrf_field()?><input class="form-control form-control-lg text-center mb-3" name="otp" maxlength="6" pattern="[0-9]{6}" inputmode="numeric" autocomplete="one-time-code" placeholder="000000" required><button class="btn btn-success w-100">Verify &amp; Save</button></form><hr><form method="post"><?=csrf_field()?><button class="btn btn-outline-primary btn-sm" name="resend_otp">Resend OTP</button></form></div></div><?php visitor_portal_footer(); ?>
